#!/usr/bin/env python3
"""Review documents for the spoken-Uzbek-only voice text (generated by plan_uz.py, nothing is synthesised):

  docs/video/voice_uz/SPOKEN_VS_SUBTITLE.md     per video: line id | subtitle | voice text | tokens replaced/dropped
  docs/video/voice_uz/GLOSSARY_UZ_ONLY.csv      term | spoken Uzbek form | kind | where used | approval needed
  tool/tts/lexicon/uz_voice_vocab.txt           every word that occurs in a voice text (allowlist used by the tests)

The vocabulary file is a REVIEWED snapshot: a new word in any voice text makes the offline test fail until a person
has looked at the word (ordinary Uzbek word / loanword in Uzbek orthography / approved name) and added it.
"""
from __future__ import annotations

import csv
import json
import re
from pathlib import Path

import uz_prep

WORD_RX = re.compile(r"[a-zA-Zʻ‘’']+")

# English / letter-name respellings that must never be spoken (checked by the tests against the vocabulary)
FORBIDDEN_WORDS = {
    # letter names as used by the old respellings
    "pe", "pi", "de", "di", "ef", "ge", "gi", "ji", "dji", "je", "si", "se", "ku", "kyu", "em", "en", "er", "ar", "es",
    "el", "ka", "ha", "ye", "ay", "dabl", "bi", "vi", "ve", "iks", "zet", "yu", "te", "ti",
    # old respellings / English words
    "kidigo", "leb", "livi", "gaid", "wbc", "pdf", "csv", "qr", "qc", "sd", "ifu", "sop", "ref", "gc", "ms",
    "pcr", "qpcr", "egfr", "kdigo", "labguide", "guide", "westgard", "levey", "jennings", "blood", "cell", "uestgard",
}
# the only foreign-looking tokens that may be spoken: personal names / brand in plain Uzbek spelling (NEEDS_OWNER_APPROVAL)
APPROVED_NAMES = {"lab", "gayd", "levi", "jenings", "vestgard", "buger", "lambert", "ber", "peltye"}
ALLOWED_SHORT = {"u", "va", "bu", "da", "ga", "ni", "ki", "bo", "to", "yo", "ol", "et", "uz", "ho", "na"}


def words(text: str) -> list[str]:
    """Lower-case word forms of a voice text (hyphenated compounds are split; apostrophes stay inside words)."""
    out = []
    for w in WORD_RX.findall(text.lower()):
        w = w.strip("'‘’ʻ")
        if w:
            out.append(w)
    return out


def esc(s: str) -> str:
    return s.replace("|", "\\|").replace("\n", " ")


def tokens_cell(items: list[dict]) -> str:
    parts = []
    nums = False
    for u in items:
        if u["kind"] == "number":
            nums = True
            continue
        if u["kind"] in ("watch",):
            continue
        if u["action"] == "dropped":
            parts.append("**%s** dropped%s" % (u["term"], " [OWNER]" if u["approval"] == "yes" else ""))
        elif u["kind"] in ("unit", "symbol") and u["term"] not in ("m/z",):
            parts.append("%s -> %s" % (u["written"].strip(), u["spoken"].strip()))
        else:
            parts.append("**%s** -> %s%s" % (u["term"], u["spoken"] or "(nothing)", " [OWNER]" if u["approval"] == "yes" else ""))
    if nums:
        parts.append("numerals -> words")
    seen, out = set(), []
    for p in parts:
        if p not in seen:
            seen.add(p)
            out.append(p)
    return "; ".join(out) if out else "-"


def where(lines: list[str], per_video_cap: int = 99) -> str:
    return " ".join(lines)


def kind_label(k: str) -> str:
    return {"abbr": "abbreviation", "name": "personal name / brand", "label": "label", "rule": "QC rule name",
            "formula": "formula", "symbol": "symbol", "unit": "unit", "number": "number pattern",
            "watch": "loanword kept (Uzbek orthography)", "term": "term"}.get(k, k)


def number_category(term: str) -> str:
    if term.startswith("decimal ") or re.match(r"number \d+,\d+", term):
        return "decimal N,M"
    if term.startswith("number "):
        return "integer"
    return term


def write_all(plans: dict, all_used: dict, repo: Path) -> None:
    lex = uz_prep.load_lexicon()
    # ---- collect ----------------------------------------------------------------------------
    owner: dict[str, dict] = {}
    gloss: dict[tuple, dict] = {}
    lexterm_all = {t["term"]: t for t in lex["terms"]}
    for vid, plan in plans.items():
        for lid, items in all_used[vid].items():
            for u in items:
                ref = "%s:%s" % (vid, lid)
                if u["approval"] == "yes":
                    e = owner.setdefault(u["term"], {"spoken": u["spoken"], "kind": u["kind"], "note": u["note"],
                                                     "action": u["action"], "refs": []})
                    e["refs"].append(ref)
                term = u["term"]
                written = u["written"]
                spoken = u["spoken"]
                kind = u["kind"]
                if kind == "number":
                    term = number_category(term)
                    cat = term
                    written, spoken = {"decimal N,M": ("0,486", "nol vergul to‘rt yuz sakson olti"),
                                       "integer": ("88", "sakson sakkiz"),
                                       "range N–M": ("2–5", "ikkidan beshgacha"),
                                       "N-noun ordinal": ("22-siklda", "yigirma ikkinchi siklda"),
                                       "N % i": ("10 % i", "o‘n foizi")}.get(cat, (written, spoken))
                    note = "numbers are always spelled out in Uzbek words (synth.py number words)"
                else:
                    note = u["note"]
                form = None
                if term in lexterm_all and kind != "number":
                    base = lexterm_all[term]["spoken"]
                    if spoken.lower().startswith(base.lower()):
                        form, spoken = spoken, base          # keep one row per term; inflected forms go to the note
                k = (term, spoken if kind != "number" else cat)
                g = gloss.setdefault(k, {"term": term, "spoken": spoken if kind != "number" else spoken, "kind": kind,
                                         "refs": [], "approval": "no", "note": note, "action": u["action"], "forms": set()})
                if form and form != spoken:
                    g["forms"].add(form)
                if u["approval"] == "yes":
                    g["approval"] = "yes"
                if ref not in g["refs"]:
                    g["refs"].append(ref)
    # terms of the lexicon that are not used in the nine scripts (reusable for other apps)
    for t in lex["terms"]:
        if not any(g["term"] == t["term"] for g in gloss.values()):
            gloss[(t["term"], t["spoken"])] = {"term": t["term"], "spoken": t["spoken"] or "(dropped)", "kind": t["kind"],
                                               "refs": [], "approval": t["approval"], "note": t["note"], "action": t["action"], "forms": set()}

    for term, spoken, note in (("−", "minus", "minus sign before a number (synth.py)"),
                               ("%", "foiz", "percent sign (synth.py); '10 % i' -> 'o‘n foizi'"),
                               ("mmol/L", "millimol litr", "unit after a number (synth.py unit table; 5 mmol/L -> besh millimol litr)")):
        if not any(g["term"] == term for g in gloss.values()):
            refs = ["%s:%s" % (vid, l["id"]) for vid, pl in plans.items() for l in pl["lines"] if term in l["text_uz"]]
            gloss[(term, spoken)] = {"term": term, "spoken": spoken, "kind": "symbol" if term != "mmol/L" else "unit",
                                     "refs": refs, "approval": "no", "note": note, "action": "replaced", "forms": set()}
    # ---- GLOSSARY_UZ_ONLY.csv -----------------------------------------------------------------
    rows = sorted(gloss.values(), key=lambda g: ({"name": 0, "abbr": 1, "label": 2, "rule": 3, "formula": 4, "unit": 5,
                                                   "symbol": 6, "number": 7, "watch": 8}.get(g["kind"], 9), g["term"].lower()))
    gp = repo / "docs/video/voice_uz/GLOSSARY_UZ_ONLY.csv"
    with gp.open("w", encoding="utf-8", newline="") as f:
        w = csv.writer(f)
        w.writerow(["term", "spoken Uzbek form", "kind", "where used", "approval needed yes/no", "note"])
        for g in rows:
            w.writerow([g["term"], g["spoken"].strip() or "(dropped from the voice)", kind_label(g["kind"]),
                        " ".join(g["refs"]) if g["refs"] else "(not in the 9 videos; kept for other apps)",
                        g["approval"], g["note"] + ("; forms in the texts: " + ", ".join(sorted(g["forms"])) if g.get("forms") else "")])

    # ---- SPOKEN_VS_SUBTITLE.md ----------------------------------------------------------------
    md = ["# Voice text versus on-screen subtitle (spoken-Uzbek-only)", "",
          "Owner's rule from listening tests: the UzbekVoice `shoira` voice cannot read English/Latin terms and letter-by-letter "
          "respellings ('pe de ef', 'e ge ef er') sound bad. So the **voice text contains only ordinary Uzbek words**; the "
          "**on-screen subtitles are unchanged** and keep PDF, eGFR, GC-MS, mmol/L ... (normal in dubbing: the voice says the Uzbek "
          "equivalent while the screen shows the abbreviation). Numbers are always spelled in Uzbek words. "
          "Status: **nobody has listened, no TTS was called**; every row is NEEDS_NATIVE_REVIEW. Generated by "
          "`python3 tool/tts/plan_uz.py` from `tool/tts/lexicon/spoken_uz_only.json`; reusable glossary: `GLOSSARY_UZ_ONLY.csv`.", "",
          "Replacement order used: (a) the standard Uzbek/Russian-lab term, (b) a short descriptive Uzbek phrase, (c) dropped from the voice "
          "only when the sentence stays correct without it, (d) personal names and the brand: plain Uzbek spelling, owner approval.", "",
          "## NEEDS_OWNER_APPROVAL", "",
          "Personal names, replacements I am not sure of, and everything dropped or rewritten that carried meaning. "
          "`[OWNER]` marks these rows in the tables below.", ""]
    order = {"name": 0, "abbr": 1, "label": 2, "rule": 3, "formula": 4, "symbol": 5}
    lexterm = {t["term"]: t for t in lex["terms"]}
    for term, e in sorted(owner.items(), key=lambda kv: (order.get(kv[1]["kind"], 9), kv[0])):
        refs = e["refs"]
        shown = " ".join(refs[:4]) + (" (+%d more)" % (len(refs) - 4) if len(refs) > 4 else "")
        spoken = lexterm[term]["spoken"] if term in lexterm else e["spoken"]
        md.append("* **%s** (%s, %s) -> `%s`; %s. %s" % (
            term, kind_label(e["kind"]), "dropped" if e["action"] == "dropped" else "replaced",
            spoken or "(nothing spoken)", shown, e["note"]))
    md += ["", "Not flagged but worth a native listen: the ordinary loanwords kept as written (analizator, kyuveta, "
           "termistor, kvadrupol, derivatizatsiya, osmolyallik ...) - see `pronunciation_uz.csv` per video, kind `watch`.", ""]
    for vid, plan in plans.items():
        md += ["## %s" % vid, "", "| line | subtitle text (on screen) | voice text | tokens replaced / dropped |", "|---|---|---|---|"]
        for l in plan["lines"]:
            md.append("| %s | %s | %s | %s |" % (l["id"], esc(l["text_uz"]), esc(l["text_tts"]),
                                                esc(tokens_cell(all_used[vid][l["id"]]))))
        md.append("")
    (repo / "docs/video/voice_uz/SPOKEN_VS_SUBTITLE.md").write_text("\n".join(md), encoding="utf-8")

    # ---- vocabulary snapshot ------------------------------------------------------------------
    vocab = set()
    for plan in plans.values():
        for l in plan["lines"]:
            vocab.update(words(l["text_tts"]))
            sg = l.get("suggested") or {}
            if sg.get("text_tts"):
                vocab.update(words(sg["text_tts"]))
    for t in lex["terms"]:
        vocab.update(words(t["spoken"]))
    for ov in lex.get("line_overrides", {}).values():
        vocab.update(words(ov["spoken"]))
    for lt in lex.get("line_terms", {}).values():
        for v in lt.values():
            vocab.update(words(v))
    (repo / "tool/tts/lexicon/uz_voice_vocab.txt").write_text(
        "# Reviewed vocabulary of the Uzbek voice texts (one lower-case word per line; generated by plan_uz.py).\n"
        "# Every word is an ordinary Uzbek word, a loanword in Uzbek orthography, or an approved name (lab gayd levi jenings vestgard buger lambert ber peltye).\n"
        "# NEVER add letter names, abbreviations or English words here; the offline test refuses them.\n"
        + "\n".join(sorted(vocab)) + "\n", encoding="utf-8")
